function useCtr(t,d=1100){const[c,sC]=useState(0);const p=useRef(0);useEffect(()=>{if(!t&&!p.current)return;const s=p.current,t0=Date.now();const i=setInterval(()=>{const pr=Math.min((Date.now()-t0)/d,1);sC(Math.round(s+(t-s)*(1-Math.pow(1-pr,3))));if(pr>=1)clearInterval(i)},16);p.current=t;return()=>clearInterval(i)},[t,d]);return c}
const gf=(r,...k)=>{for(const n of k){const v=r.fields[n];if(v!==undefined&&v!==null&&v!=="")return v}return null};
const gV=r=>{const v=gf(r,"AI Verdict","Verdict");if(!v)return null;const l=v.toLowerCase();return l.includes("hot")?"Hot":l.includes("warm")?"Warm":l.includes("cold")?"Cold":l.includes("high")?"High":l.includes("not")?"Not Relevant":v};
const gS=r=>{const s=gf(r,"AI Score","Score");return s?parseInt(s):null};
const vc=v=>{if(!v)return"";const l=v.toLowerCase();return l.includes("hot")?"v-hot":l.includes("warm")?"v-warm":l.includes("cold")?"v-cold":l.includes("high")?"v-high":""};
