function RKpi({items}){return<div style={{display:"grid",gridTemplateColumns:`repeat(${Math.min(items.length,5)},1fr)`,gap:10,marginBottom:14}}>{items.map((k,i)=><div key={i} style={{padding:"12px 14px",borderRadius:10,background:"var(--s)",border:"1px solid #F0EBE5",textAlign:"center"}}><div style={{fontFamily:J,fontWeight:700,fontSize:"1.3rem",color:k.color||CL.br,marginBottom:2}}>{k.value}</div><div style={{fontSize:".7rem",color:"var(--t2)",fontWeight:500}}>{k.label}</div></div>)}</div>}
function RPie({title,data}){return<div style={{marginBottom:14}}>{title&&<h4 style={{fontFamily:F,fontWeight:700,fontSize:".9rem",marginBottom:8}}>{title}</h4>}<div style={{display:"flex",alignItems:"center",gap:16}}><ResponsiveContainer width="50%" height={170}><PieChart><Pie data={data} cx="50%" cy="50%" innerRadius={42} outerRadius={70} paddingAngle={3} dataKey="value">{data.map((d,i)=><Cell key={i} fill={d.color||Object.values(CL)[i%7]}/>)}</Pie><Tooltip contentStyle={{fontSize:".78rem",borderRadius:8,border:"1px solid #E8E0D8"}}/></PieChart></ResponsiveContainer><div style={{display:"flex",flexDirection:"column",gap:5}}>{data.map((d,i)=><div key={i} style={{display:"flex",alignItems:"center",gap:6}}><div style={{width:8,height:8,borderRadius:2,background:d.color||Object.values(CL)[i%7],flexShrink:0}}/><span style={{fontSize:".76rem",color:"var(--t2)"}}>{d.name}</span><span style={{fontFamily:J,fontSize:".74rem",fontWeight:600,marginLeft:"auto"}}>{d.value}</span></div>)}</div></div></div>}
function RBar({title,data}){return<div style={{marginBottom:14}}>{title&&<h4 style={{fontFamily:F,fontWeight:700,fontSize:".9rem",marginBottom:8}}>{title}</h4>}<ResponsiveContainer width="100%" height={Math.max(150,data.length*30)}><BarChart data={data} layout="vertical" margin={{left:100,right:16}}><XAxis type="number" tick={{fontSize:10,fontFamily:J}}/><YAxis type="category" dataKey="name" tick={{fontSize:11}} width={95}/><Tooltip contentStyle={{fontSize:".78rem",borderRadius:8,border:"1px solid #E8E0D8"}}/><Bar dataKey="value" radius={[0,4,4,0]}>{data.map((d,i)=><Cell key={i} fill={d.color||CL.br}/>)}</Bar></BarChart></ResponsiveContainer></div>}
