const[calData,sCalData]=useState([]);const[calLoad,sCalLoad]=useState(false);const[saveModal,sSaveModal]=useState(null);const[saving,sSaving]=useState(false);const[calWeek,sCalWeek]=useState(null);const[calExp,sCalExp]=useState(null);
const[leadModal,sLeadModal]=useState(null);const[selLeads,sSelLeads]=useState([]);const[leadSearch,sLeadSearch]=useState("");
