const load=useCallback(async(r=false)=>{if(r)sRfr(true);try{let a=[],o=null;do{const r=await fetch(`https://api.airtable.com/v0/${AB}/${AT}?pageSize=100${o?`&offset=${o}`:""}`,{headers:{Authorization:`Bearer ${AP}`}});if(!r.ok)throw new Error(`${r.status}`);const d=await r.json();a=[...a,...(d.records||[])];o=d.offset||null}while(o);setRecs(a);sSyn(new Date());sErr(null)}catch(e){sErr(e.message)}finally{sLd(false);sRfr(false)}},[]);
useEffect(()=>{load()},[load]);
useEffect(()=>{const i=setInterval(()=>load(),30000);return()=>clearInterval(i)},[load]);

useEffect(()=>{if(vfD.current||!vfR.current||tab!=="voiceflow")return;vfD.current=true;setTimeout(()=>{const el=document.createElement("script");el.src="https://cdn.voiceflow.com/widget-next/bundle.mjs";el.type="text/javascript";el.onload=()=>{if(window.voiceflow?.chat)window.voiceflow.chat.load({verify:{projectID:VF},url:"https://general-runtime.voiceflow.com",versionID:"production",render:{mode:"embedded",target:vfR.current},autostart:true})};document.head.appendChild(el)},600)},[vfR.current,tab]);

const tot=recs.length;const qal=recs.filter(r=>gf(r,"AI Processed")).length;
const ems=recs.filter(r=>gf(r,"Email Generated","Generated Email","Email Body","AI Email")).length;
const wor=recs.filter(r=>gf(r,"Email Worthy")).length;
const scs=recs.map(gS).filter(s=>s!==null);const avg=scs.length?Math.round(scs.reduce((a,b)=>a+b,0)/scs.length):0;
const hot=recs.filter(r=>{const v=gV(r);return v==="Hot"||v==="High"}).length;
const wrm=recs.filter(r=>gV(r)==="Warm").length;
const enr=recs.filter(r=>gf(r,"Growth Score","Enriched","Web Content")).length;
const cn={};recs.forEach(r=>{const c=gf(r,"Country")||"Unknown";cn[c]=(cn[c]||0)+1});
const tc=Object.entries(cn).sort((a,b)=>b[1]-a[1]).slice(0,5);
const aT=useCtr(tot),aQ=useCtr(qal),aE=useCtr(ems),aS=useCtr(avg);

const prepLeads=()=>recs.map(r=>({name:gf(r,"Company name","Company Name","Name","Company")||"",country:gf(r,"Country")||"",city:gf(r,"City / Region")||"",score:gS(r),verdict:gV(r),products:gf(r,"Recommended Products","Products")||"",pain:gf(r,"Pain Points","AI Pain Points")||"",handled:gf(r,"Products Handled")||"",employees:gf(r,"Employee count")||"",revenue:gf(r,"Annual Revenue")||"",sector:gf(r,"Industry","Sector")||"",subIndustry:gf(r,"Sub-Industry")||"",competitor:gf(r,"Competitor Equipment")||"",growth:gf(r,"Growth Score")||"",expansion:gf(r,"Expansion Plans")||"",fit:gf(r,"Newtec Fit Analysis")||"",age:gf(r,"Company Age")||"",lang:gf(r,"Contact Language")||"",timing:gf(r,"Timing Opportunity")||"",invest:gf(r,"Investment Readiness")||"",equip:gf(r,"Equipment Signals")||"",certs:gf(r,"Certifications")||"",source:gf(r,"Source")||"",priority:gf(r,"Priority Tier")||"",emailWorthy:gf(r,"Email Worthy")||"",processed:gf(r,"AI Processed")||"",desc:gf(r,"Company Description")||"",linkedin:gf(r,"LinkedIn URL")||"",phone:gf(r,"Phone")||""})).filter(l=>l.name);

/* AI Intelligence send */
const sendChat=async()=>{if(!ci.trim()||cld)return;const q=ci.trim();sCI("");sCH(p=>[...p,{role:"user",text:q}]);sCld(true);
try{const r=await fetch("/api/chat",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({question:q,leads:prepLeads()})});
if(!r.ok)throw new Error(`${r.status}`);const d=await r.json();sCH(p=>[...p,{role:"ai",text:d.answer||"",charts:d.charts||[]}])}
catch(e){sCH(p=>[...p,{role:"ai",text:"Error connecting to AI. Check CLAUDE_API_KEY in Vercel env vars.",charts:[]}])}
sCld(false);setTimeout(()=>ceR.current?.scrollIntoView({behavior:"smooth"}),100)};

/* Content Lab send */
const sendContent=async(topic)=>{const t=topic||ct.trim();if(!t||cgl)return;sCT("");sCGL(true);sCG(null);
try{const r=await fetch("/api/content",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({topic:t,language:clang,profiles:selProf,channels:selChan,leads:prepLeads()})});
if(!r.ok)throw new Error(`${r.status}`);const d=await r.json();sCG(d)}catch(e){sCG({error:e.message})}sCGL(false)};

/* Calendar functions */
const loadCal=async()=>{sCalLoad(true);try{const r=await fetch("/api/calendar");if(r.ok){const d=await r.json();sCalData(d.records||[])}}catch(e){console.error(e)}sCalLoad(false)};
const saveToCal=async(data)=>{sSaving(true);try{const r=await fetch("/api/calendar",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(data)});if(r.ok){await loadCal();sSaveModal(null)}}catch(e){alert("Error saving")}sSaving(false)};

/* Webhook + polling for S2/S3 */
const fetchLeadData=async(ids)=>{const fml=`OR(${ids.map(id=>`RECORD_ID()="${id}"`).join(",")})`;const r=await fetch(`https://api.airtable.com/v0/${AB}/${AT}?filterByFormula=${encodeURIComponent(fml)}`,{headers:{Authorization:`Bearer ${AP}`}});if(!r.ok)return null;const d=await r.json();return(d.records||[]).map(rec=>({id:rec.id,name:gf(rec,"Company name")||"Unknown",country:gf(rec,"Country")||"",city:gf(rec,"City / Region")||"",score:gS(rec),verdict:gV(rec),reason:gf(rec,"AI Reason")||"",pain:gf(rec,"Pain Points")||"",products:gf(rec,"Recommended Products")||"",handled:gf(rec,"Products Handled")||"",email:gf(rec,"Email Draft","Email Body")||"",angle:gf(rec,"Outreach Angle")||"",fit:gf(rec,"Newtec Fit Analysis")||"",tier:gf(rec,"Priority Tier")||"",tone:gf(rec,"Email Tone")||"",status:gf(rec,"Status")||"",employees:gf(rec,"Employee count")||"",revenue:gf(rec,"Annual Revenue")||"",age:gf(rec,"Company Age")||"",growth:gf(rec,"Growth Score")||"",competitor:gf(rec,"Competitor Equipment")||"",equip:gf(rec,"Equipment Signals")||"",expansion:gf(rec,"Expansion Plans")||"",invest:gf(rec,"Investment Readiness")||"",timing:gf(rec,"Timing Opportunity")||"",certs:gf(rec,"Certifications")||"",lang:gf(rec,"Contact Language")||"",website:gf(rec,"Website")||"",processed:!!gf(rec,"AI Processed"),emailGen:!!gf(rec,"Email Generated","Generated Email","Email Body")}))};
const runScenario=async(url,label)=>{if(!selLeads.length)return;const ids=[...selLeads];sRunProg({total:ids.length,done:0,label,errors:[]});sRunResults(null);sPollMsg("");const before=await fetchLeadData(ids);const beforeMap={};(before||[]).forEach(l=>{beforeMap[l.id]={score:l.score,processed:l.processed,emailGen:l.emailGen}});for(let i=0;i<ids.length;i++){try{const r=await fetch("/api/webhook",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({url,record_id:ids[i]})});const d=await r.json();if(!r.ok||!d.ok)sRunProg(p=>({...p,errors:[...(p.errors||[]),ids[i]]}));sRunProg(p=>({...p,done:i+1}))}catch(e){console.error(e);sRunProg(p=>({...p,done:i+1,errors:[...(p.errors||[]),ids[i]]}))}if(i<ids.length-1)await new Promise(r=>setTimeout(r,5000))}sPollMsg("Webhooks sent. Waiting for Make.com to process...");let gotResults=false;for(let p=0;p<18;p++){await new Promise(r=>setTimeout(r,10000));sPollMsg(`Polling Airtable... ${(p+1)*10}s elapsed`);try{const fresh=await fetchLeadData(ids);if(fresh){let changed=0;fresh.forEach(l=>{const b=beforeMap[l.id]||{};if(l.score!==b.score||l.emailGen!==b.emailGen)changed++});if(changed>0||p>=5){sRunResults(fresh);gotResults=true;sPollMsg(changed>0?`${changed} lead${changed>1?"s":""} updated!`:"Results loaded");break}}}catch(e){console.error(e)}}if(!gotResults){const final=await fetchLeadData(ids);if(final)sRunResults(final);sPollMsg("Showing current data.")}sRunProg(p=>({...p,done:ids.length,finished:true}));load(true)};

